def turn_to(side):
    if side == "left":
        turn_left()
    elif side == "right":
        turn_right()


def turn_from(side):
    if side == "left":
        turn_right()
    elif side == "right":
        turn_left()


def back_up():
    turn_left()
    turn_left()
    if guard_ahead():
        hide()
    step(1)
    turn_left()
    turn_left()
